      html: '<h4>Inline Progress Bar</h4>\n<div class="progress-block">\n  <label>Simple Layout</label>\n  <div class="progress">\n    <progress\n      [value]="inlineProgress"\n      max="100"\n      [attr.data-displayval]="inlineProgress + \'%\'"\n    ></progress>\n  </div>\n  <span>More text</span>\n</div>\n\n<div class="progress-block">\n  <label>Complex Layout</label>\n  <div class="progress-group">\n    <div class="clr-row">\n      <div class="clr-col-6">Left</div>\n      <div class="clr-col-6 text-right">Right</div>\n    </div>\n    <div class="progress-static">\n      <div\n        class="progress-meter"\n        [attr.data-value]="inlineStaticProgbarValue"\n        [attr.data-displayval]="inlineStaticProgbarValue + \'%\'"\n      ></div>\n    </div>\n    <div class="clr-row">\n      <div class="clr-col-6">Left</div>\n      <div class="clr-col-6 text-right">Right</div>\n    </div>\n  </div>\n  <span>More text</span>\n</div>\n\n<h4>Labeled, Static Progress Bar</h4>\n<div class="progress-block">\n  <label>Complex Layout</label>\n  <div class="progress-group">\n    <div class="clr-row">\n      <div class="clr-col-6">Left</div>\n      <div class="clr-col-6 text-right">Right</div>\n    </div>\n    <div class="progress-static labeled danger">\n      <div\n        class="progress-meter"\n        [attr.data-value]="staticLabeledProgbarValue"\n        [attr.data-displayval]="staticLabeledProgbarValue + \'%\'"\n      ></div>\n      <span>{{ staticLabeledProgbarValue }}%</span>\n    </div>\n    <div class="clr-row">\n      <div class="clr-col-6">Left</div>\n      <div class="clr-col-6 text-right">Right</div>\n    </div>\n  </div>\n</div>\n\n<h4>Stacked Progress Bars</h4>\n<div class="progress-block">\n  <label>Stacked Layout</label>\n  <div class="progress-group">\n    <div class="progress-static labeled danger">\n      <div\n        class="progress-meter"\n        [attr.data-value]="staticDangerValue"\n        [attr.data-displayval]="staticDangerValue + \'%\'"\n      ></div>\n      <span>{{ staticDangerValue }}%</span>\n    </div>\n    <div class="progress-static labeled">\n      <div\n        class="progress-meter"\n        [attr.data-value]="staticLabeledProgbarValue"\n        [attr.data-displayval]="staticLabeledProgbarValue + \'%\'"\n      ></div>\n      <span>{{ staticLabeledProgbarValue }}%</span>\n    </div>\n    <div class="progress-static labeled success">\n      <div\n        class="progress-meter"\n        [attr.data-value]="staticSuccessValue"\n        [attr.data-displayval]="staticSuccessValue + \'%\'"\n      ></div>\n      <span>{{ staticSuccessValue }}%</span>\n    </div>\n  </div>\n</div>\n\n<div class="progress-block">\n  <label>Stacked (but resized) Layout</label>\n  <div class="progress-group" style="font-size: 1px">\n    <div class="progress-static danger">\n      <div\n        class="progress-meter"\n        [attr.data-value]="staticDangerValue"\n        [attr.data-displayval]="staticDangerValue + \'%\'"\n      ></div>\n      <span>{{ staticDangerValue }}%</span>\n    </div>\n    <div class="progress-static">\n      <div\n        class="progress-meter"\n        [attr.data-value]="staticLabeledProgbarValue"\n        [attr.data-displayval]="staticLabeledProgbarValue + \'%\'"\n      ></div>\n      <span>{{ staticLabeledProgbarValue }}%</span>\n    </div>\n    <div class="progress-static success">\n      <div\n        class="progress-meter"\n        [attr.data-value]="staticSuccessValue"\n        [attr.data-displayval]="staticSuccessValue + \'%\'"\n      ></div>\n      <span>{{ staticSuccessValue }}%</span>\n    </div>\n  </div>\n</div>\n\n<p><button class="btn btn-outline" (click)="setNewValues()">Load New Values</button></p>\n',
